WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id, brand ORDER BY price DESC, id) AS rn FROM products) ranked WHERE rn = 1) SELECT CASE WHEN cost >= 730 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, COUNT(*) FILTER (WHERE category = 'Home') AS home_rows, SIZE(COLLECT_SET(brand)) AS num_brands, CORR(price, stock_qty) AS corr_price_stock_qty, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids FROM ranked GROUP BY CASE WHEN cost >= 730 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING num_brands < 1000 ORDER BY num_brands DESC NULLS LAST;
